{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    children = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in fields):
            raise ValueError("node missing required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(float(utility)):
            raise ValueError("utility must be finite numeric")
        by_id[node_id] = node
        children[node_id] = []

    roots = []
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        if parent is None:
            roots.append(node_id)
        else:
            if parent not in by_id:
                raise ValueError("parent must reference an existing node")
            children[parent].append(node_id)
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("invalid parent depth")
    if len(roots) != 1 or by_id[roots[0]]["depth"] != 0:
        raise ValueError("tree must have exactly one depth-zero root")

    seen = set()
    stack = [roots[0]]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError("tree contains a cycle")
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(nodes):
        raise ValueError("tree is disconnected")

    if not required.issubset({node["symbol"] for node in nodes}):
        raise ValueError("required symbol is absent")

    active = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id not in active or not node["removable"] or node["parent"] is None:
            continue
        if node["symbol"] in required:
            continue
        if any(child in active for child in children[node_id]):
            continue
        remaining_symbols = {by_id[other]["symbol"] for other in active if other != node_id}
        if not required.issubset(remaining_symbols):
            continue
        active.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(active),
    }"}
